ALTER TABLE restaurant_settings ADD COLUMN demo_tax_bps integer NOT NULL DEFAULT 0 CHECK(demo_tax_bps BETWEEN 0 AND 2500);
ALTER TABLE orders ADD COLUMN discount_paise integer NOT NULL DEFAULT 0 CHECK(discount_paise>=0 AND discount_paise<=subtotal_paise), ADD COLUMN tax_paise integer NOT NULL DEFAULT 0 CHECK(tax_paise>=0), ADD COLUMN coupon_code text;
ALTER TABLE orders ADD CHECK(total_paise=subtotal_paise-discount_paise+tax_paise);
CREATE TABLE coupons (restaurant_id uuid NOT NULL REFERENCES restaurants(id), code text NOT NULL, percent_bps integer NOT NULL CHECK(percent_bps BETWEEN 1 AND 10000), minimum_paise integer NOT NULL DEFAULT 0 CHECK(minimum_paise>=0), maximum_discount_paise integer CHECK(maximum_discount_paise>0), maximum_uses integer NOT NULL CHECK(maximum_uses BETWEEN 1 AND 10000), eligible_menu_id text, expires_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(restaurant_id,code), FOREIGN KEY(restaurant_id,eligible_menu_id) REFERENCES menu_items(restaurant_id,id));
CREATE TABLE coupon_usages (restaurant_id uuid NOT NULL, order_id uuid NOT NULL, code text NOT NULL, discount_paise integer NOT NULL CHECK(discount_paise>0), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(restaurant_id,order_id), FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id), FOREIGN KEY(restaurant_id,code) REFERENCES coupons(restaurant_id,code));
